/// How far a mode reaches into an area: the paths it reaches, and the
/// widest access it has to any, none where it reaches none.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Reach {
    pub access: Option<Access>,
    pub paths: Vec<String>,
}

/// What a run of each of `kinds` reaches of each area of the project at
/// `project_dir`, as its profile compiles today: a row per area, a reach
/// per kind; a kind whose profile can't be compiled gives why instead.
pub fn reach(
    kinds: &[ProfileKind],
    agent: crate::agent::Agent,
    project_dir: &Path,
) -> Vec<(Area, Vec<Result<Reach, String>>)> {
    let project = dunce::canonicalize(project_dir).unwrap_or_else(|_| project_dir.to_path_buf());
    let (code, spec) = Classification::load(project_dir)
        .resolve(&project)
        .unwrap_or_default();
    let resolved = |paths: Vec<PathBuf>| -> Vec<PathBuf> {
        paths
            .into_iter()
            .map(|path| dunce::canonicalize(&path).unwrap_or(path))
            .collect()
    };
    let areas: Vec<(Area, Vec<PathBuf>)> = vec![
        (Area::Code, resolved(code)),
        (Area::SpecSource, resolved(spec)),
        (Area::Reference, resolved(vec![project.join(agent.directory()).join("reference")])),
        (Area::ProjectData, resolved(vec![project.join(crate::hidden_anchor::APP_DIR)])),
    ];
    let compiled: Vec<Result<Compiled, String>> = kinds
        .iter()
        .map(|kind| {
            profile(*kind, agent, project_dir, &RunFiles::default())
                .and_then(|policy| compile(&policy))
                .map_err(|refused| refused.message)
        })
        .collect();
    let of = |rules: Vec<&Rule>, compiled: &Compiled| Reach {
        access: rules.iter().map(|rule| rule.access).max(),
        paths: rules.iter().map(|rule| relative(&compiled.project, &rule.path)).collect(),
    };
    let mut rows = Vec::new();
    for (area, paths) in &areas {
        let cells = compiled
            .iter()
            .map(|compiled| {
                let compiled = compiled.as_ref().map_err(Clone::clone)?;
                // What covers the area, or lies within it.
                let rules: Vec<&Rule> = compiled
                    .rules
                    .iter()
                    .filter(|rule| rule.path.starts_with(&compiled.project))
                    .filter(|rule| {
                        paths.iter().any(|path| {
                            !compiled.denied.iter().any(|denied| path.starts_with(denied))
                                && (path.starts_with(&rule.path) || rule.path.starts_with(path))
                        })
                    })
                    .collect();
                Ok(of(rules, compiled))
            })
            .collect();
        rows.push((*area, cells));
    }
    // Everything else: what is granted in the project outside the areas.
    let all: Vec<&PathBuf> = areas.iter().flat_map(|(_, paths)| paths).collect();
    let cells = compiled
        .iter()
        .map(|compiled| {
            let compiled = compiled.as_ref().map_err(Clone::clone)?;
            let rules: Vec<&Rule> = compiled
                .rules
                .iter()
                .filter(|rule| rule.path.starts_with(&compiled.project))
                .filter(|rule| !all.iter().any(|path| rule.path.starts_with(path)))
                // The fluency files and guidance every run reads aren't the
                // rest of the project.
                .filter(|rule| {
                    !matches!(
                        rule.path.file_name().and_then(|name| name.to_str()),
                        Some("CLAUDE.md" | "AGENTS.md" | ".mcp.json")
                    )
                })
                .collect();
            Ok(of(rules, compiled))
        })
        .collect();
    rows.push((Area::EverythingElse, cells));
    rows
}

