/// Reads, in the background, whether the sandbox can run here.
fn read_sandbox(&mut self, cx: &mut Context<Self>) {
    let read = cx.background_spawn(async { crate::sandbox::status() });
    self._sandbox_read = cx.spawn(async move |this, cx| {
        let status = read.await;
        this.update(cx, |this, cx| {
            this.sandbox = Some(status);
            cx.notify();
        })
        .ok();
    });
}

/// Runs Test sandbox: a short set of the hostile checks, in a temporary
/// project, each saying whether the system refused it.
fn test_sandbox(&mut self, cx: &mut Context<Self>) {
    self.testing = true;
    let run = cx.background_spawn(async { crate::sandbox::self_test() });
    self._sandbox_test = cx.spawn(async move |this, cx| {
        let found = run.await;
        this.update(cx, |this, cx| {
            this.sandbox_test = Some(found);
            this.testing = false;
            cx.notify();
        })
        .ok();
    });
    cx.notify();
}

/// Changes the open project's classification by `change`, saved at once.
fn classify(&mut self, change: impl FnOnce(&mut Classification), cx: &mut Context<Self>) {
    let Some(project_dir) = ProjectDirectory::get(cx) else {
        return;
    };
    let mut classification = Classification::load(&project_dir);
    change(&mut classification);
    self.classification_error = classification
        .save(&project_dir)
        .err()
        .map(|err| format!("{err}").into());
    cx.notify();
}

/// Adds code or spec roots, chosen with the folder browser.
fn add_root(&mut self, spec: bool, window: &mut Window, cx: &mut Context<Self>) {
    let Some(project_dir) = ProjectDirectory::get(cx) else {
        return;
    };
    let picked = cx.prompt_for_paths(PathPromptOptions {
        files: true,
        directories: true,
        multiple: true,
        prompt: Some("Add".into()),
    });
    cx.spawn_in(window, async move |this, cx| {
        let Ok(Ok(Some(paths))) = picked.await else {
            return;
        };
        this.update(cx, |this, cx| {
            let roots: Vec<String> = paths
                .iter()
                .filter_map(|path| path.strip_prefix(&project_dir).ok())
                .map(|path| path.to_string_lossy().replace('\\', "/"))
                .collect();
            this.classify(
                |classification| {
                    let list = if spec {
                        &mut classification.spec_roots
                    } else {
                        &mut classification.code_roots
                    };
                    for root in roots {
                        if !list.contains(&root) {
                            list.push(root);
                        }
                    }
                },
                cx,
            )
        })
        .ok();
    })
    .detach();
}

/// Adds the pattern typed as classing files as spec, or as code.
fn add_pattern(&mut self, spec: bool, window: &mut Window, cx: &mut Context<Self>) {
    let pattern = self.pattern.read(cx).value().trim().to_string();
    if pattern.is_empty() {
        return;
    }
    if globset::Glob::new(&pattern).is_err() {
        self.classification_error = Some(format!("`{pattern}` isn't a pattern").into());
        cx.notify();
        return;
    }
    self.classify(
        |classification| {
            let list = if spec {
                &mut classification.spec_patterns
            } else {
                &mut classification.code_patterns
            };
            if !list.contains(&pattern) {
                list.push(pattern.clone());
            }
        },
        cx,
    );
    self.pattern.update(cx, |input, cx| input.set_value("", window, cx));
}

/// A list of the classification's `items`, each with Remove.
fn render_classed(
    &self,
    id: &'static str,
    title: &'static str,
    items: &[String],
    remove: fn(&mut Classification, &str),
    cx: &mut Context<Self>,
) -> AnyElement {
    let muted = cx.theme().muted_foreground;
    v_flex()
        .gap_1()
        .child(div().text_sm().font_medium().child(title))
        .children(items.iter().enumerate().map(|(n, item)| {
            let item = item.clone();
            h_flex()
                .gap_2()
                .text_sm()
                .child(div().flex_1().min_w_0().truncate().child(item.clone()))
                .child(
                    Button::new(SharedString::from(format!("{id}-remove-{n}")))
                        .ghost()
                        .xsmall()
                        .label("Remove")
                        .on_click(cx.listener(move |this, _, _, cx| {
                            let item = item.clone();
                            this.classify(|classification| remove(classification, &item), cx)
                        })),
                )
        }))
        .when(items.is_empty(), |list| {
            list.child(div().text_sm().text_color(muted).child("None"))
        })
        .into_any_element()
}

/// The "Sandbox" section, as the SettingsWindowScope says: whether the
/// sandbox can run here, what it leaves out, and for the open project,
/// its classification, its Spec tasks' reading, its profiles, and Test
/// sandbox.
fn render_sandbox(&self, cx: &mut Context<Self>) -> impl IntoElement {
    let muted = cx.theme().muted_foreground;
    let danger = cx.theme().danger;
    let backend = crate::sandbox::backend_name();
    let status: AnyElement = match &self.sandbox {
        None => div().text_color(muted).child("Checking the sandbox…").into_any_element(),
        Some(Ok(enforces)) => div().child(enforces.clone()).into_any_element(),
        Some(Err(why)) => v_flex()
            .gap_1()
            .child(div().text_color(danger).child(format!(
                "{backend} can't run here: {}. No task or question will run until it can.",
                why.message
            )))
            .child(
                Button::new("settings-sandbox-docs")
                    .small()
                    .label("Sandbox documentation")
                    .on_click(|_, _, cx| cx.open_url(crate::sandbox::DOCUMENTATION)),
            )
            .into_any_element(),
    };
    let outside = div().text_sm().text_color(muted).child(
        "Outside the sandbox, and never claimed as protected: the network, through which a \
         run could fetch the project from where it is published; the harness's own service, \
         which holds what earlier conversations sent it; and the clipboard.",
    );
    let mut classification_view = None;
    let mut profiles = None;
    if let Some(project_dir) = ProjectDirectory::get(cx) {
        let classification = Classification::load(&project_dir);
        let conflict = classification.conflict(&project_dir);
        classification_view = Some(
            v_flex()
                .gap_3()
                .child(div().font_semibold().child("Classification"))
                .child(div().text_sm().text_color(muted).child(
                    "Which paths are code and which are spec, kept in .suspense/sandbox.json. \
                     A path classed as neither is denied to Code and Spec runs alike.",
                ))
                .child(self.render_classed("settings-code-roots", "Code roots", &classification.code_roots, |c, item| c.code_roots.retain(|root| root != item), cx))
                .child(
                    Button::new("settings-add-code-root")
                        .small()
                        .label("Add code root")
                        .on_click(cx.listener(|this, _, window, cx| this.add_root(false, window, cx))),
                )
                .child(self.render_classed("settings-spec-roots", "Spec roots", &classification.spec_roots, |c, item| c.spec_roots.retain(|root| root != item), cx))
                .child(
                    Button::new("settings-add-spec-root")
                        .small()
                        .label("Add spec root")
                        .on_click(cx.listener(|this, _, window, cx| this.add_root(true, window, cx))),
                )
                .child(self.render_classed("settings-code-patterns", "Code patterns", &classification.code_patterns, |c, item| c.code_patterns.retain(|pattern| pattern != item), cx))
                .child(self.render_classed("settings-spec-patterns", "Spec patterns", &classification.spec_patterns, |c, item| c.spec_patterns.retain(|pattern| pattern != item), cx))
                .child(
                    h_flex()
                        .gap_2()
                        .child(div().w(px(220.)).child(Input::new(&self.pattern).small()))
                        .child(
                            Button::new("settings-add-code-pattern")
                                .small()
                                .label("Add as code")
                                .on_click(cx.listener(|this, _, window, cx| this.add_pattern(false, window, cx))),
                        )
                        .child(
                            Button::new("settings-add-spec-pattern")
                                .small()
                                .label("Add as spec")
                                .on_click(cx.listener(|this, _, window, cx| this.add_pattern(true, window, cx))),
                        ),
                )
                .children(conflict.map(|why| div().text_sm().text_color(danger).child(why)))
                .children(self.classification_error.clone().map(|why| div().text_sm().text_color(danger).child(why)))
                .child(
                    Button::new("settings-reset-classification")
                        .small()
                        .label("Reset to project locations")
                        .on_click(cx.listener(|this, _, _, cx| {
                            let Some(project_dir) = ProjectDirectory::get(cx) else {
                                return;
                            };
                            this.classify(
                                |classification| *classification = Classification::from_locations(&project_dir),
                                cx,
                            )
                        })),
                ),
        );
        let agent = crate::agent::of_project(Some(&project_dir));
        let mut list = v_flex().gap_3().child(div().font_semibold().child("Profiles"));
        for kind in ProfileKind::SHOWN {
            let open = self.profiles_open.contains(&kind);
            let body: AnyElement = match crate::sandbox::summary(kind, agent, &project_dir) {
                Err(why) => div().text_sm().text_color(danger).child(why.message).into_any_element(),
                Ok(summary) => {
                    let line = |label: &str, items: &[String]| {
                        div().text_sm().child(format!(
                            "{label}: {}",
                            if items.is_empty() { "nothing".to_string() } else { items.join(", ") }
                        ))
                    };
                    v_flex()
                        .gap_0p5()
                        .child(line("Read-only", &summary.read_only))
                        .child(line("Read-write", &summary.read_write))
                        .child(line("Denied", &summary.denied))
                        .child(
                            Button::new(SharedString::from(format!("settings-profile-outside-{}", kind.label())))
                                .ghost()
                                .xsmall()
                                .label(format!(
                                    "{} paths outside the project{}",
                                    summary.outside.len(),
                                    if open { "" } else { " ›" }
                                ))
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    if !this.profiles_open.remove(&kind) {
                                        this.profiles_open.insert(kind);
                                    }
                                    cx.notify();
                                })),
                        )
                        .when(open, |body| {
                            body.children(summary.outside.iter().map(|path| {
                                div().pl_4().text_xs().text_color(muted).child(path.clone())
                            }))
                        })
                        .into_any_element()
                }
            };
            list = list.child(v_flex().gap_1().child(div().font_medium().child(kind.label())).child(body));
        }
        profiles = Some(list);
    }
    let test = v_flex()
        .gap_1()
        .child(
            Button::new("settings-test-sandbox")
                .small()
                .label("Test sandbox")
                .loading(self.testing)
                .disabled(self.testing)
                .on_click(cx.listener(|this, _, _, cx| this.test_sandbox(cx))),
        )
        .children(self.sandbox_test.as_ref().map(|found| match found {
            Err(why) => div().text_sm().text_color(danger).child(why.message.clone()).into_any_element(),
            Ok(checks) => v_flex()
                .gap_0p5()
                .children(checks.iter().map(|(check, refused)| {
                    div()
                        .text_sm()
                        .text_color(if *refused { muted } else { danger })
                        .child(format!("{check}: {}", if *refused { "refused" } else { "NOT refused" }))
                }))
                .into_any_element(),
        }));
    let spec_reading = self.render_spec_reading(cx);
    v_flex()
        .gap_5()
        .child(v_flex().gap_1().child(div().font_semibold().child(backend)).child(status).child(outside))
        .children(classification_view)
        .children(spec_reading)
        .children(profiles)
        .child(test)
}

/// For the open project alone: whether its Spec runs may read the code,
/// and the whole project.
fn render_spec_reading(&self, cx: &mut Context<Self>) -> Option<AnyElement> {
    let muted = cx.theme().muted_foreground;
    ProjectDirectory::get(cx).map(|project_dir| {
        let settings = crate::project_settings::ProjectSettings::load(&project_dir);
        let reads = settings.spec_reads_code;
        // Offered only while they may read the code.
        let whole = reads.then(|| {
            v_flex()
                .pl_6()
                .gap_1()
                .child(
                    crate::checkbox::checkbox(
                        "settings-spec-reads-project",
                        "Also let them read the whole project",
                    )
                    .checked(settings.spec_reads_project)
                    .on_click(cx.listener(move |this, checked: &bool, _, cx| {
                        this.set_spec_reads_project(*checked, cx)
                    })),
                )
                .child(
                    div()
                        .text_sm()
                        .text_color(muted)
                        .child(
                            "The whole project directory is granted read only, but for \
                             its .git and .suspense folders.",
                        ),
                )
        });
        v_flex()
            .gap_1()
            .child(
                crate::checkbox::checkbox("settings-spec-reads-code", "Let Spec tasks read the code")
                    .checked(reads)
                    .on_click(cx.listener(move |this, checked: &bool, _, cx| {
                        this.set_spec_reads_code(*checked, cx)
                    })),
            )
            .child(
                div()
                    .text_sm()
                    .text_color(muted)
                    .child(
                        "The code is granted read only, so Spec tasks and a Chain prompt's \
                         spec steps can read it but never change it.",
                    ),
            )
            .children(whole)
            .children(self.project_settings_error.clone().map(|error| {
                div().text_sm().text_color(cx.theme().danger).child(error)
            }))
            .into_any_element()
    })
}

/// Lets the open project's Spec runs read the code, or not, saved with
/// the project at once; from its next run.
fn set_spec_reads_code(&mut self, reads: bool, cx: &mut Context<Self>) {
    let Some(project_dir) = ProjectDirectory::get(cx) else {
        return;
    };
    let mut settings = crate::project_settings::ProjectSettings::load(&project_dir);
    settings.spec_reads_code = reads;
    // Not reading the code, they read nothing else of it either.
    if !reads {
        settings.spec_reads_project = false;
    }
    self.project_settings_error = settings
        .save(&project_dir)
        .err()
        .map(|err| format!("{err:#}").into());
    crate::debug_log::log(
        Some(&project_dir),
        format!("Spec runs may read the code: {reads}"),
    );
    cx.notify();
}

/// Lets the open project's Spec runs read the whole project too, or not,
/// saved with the project at once; from its next run.
fn set_spec_reads_project(&mut self, reads: bool, cx: &mut Context<Self>) {
    let Some(project_dir) = ProjectDirectory::get(cx) else {
        return;
    };
    let mut settings = crate::project_settings::ProjectSettings::load(&project_dir);
    settings.spec_reads_project = reads && settings.spec_reads_code;
    self.project_settings_error = settings
        .save(&project_dir)
        .err()
        .map(|err| format!("{err:#}").into());
    crate::debug_log::log(
        Some(&project_dir),
        format!("Spec runs may read the whole project: {}", settings.spec_reads_project),
    );
    cx.notify();
}

/// Saves `which` as edited.
fn save(&mut self, which: Prompt, cx: &mut Context<Self>) {
    let Some(project_dir) = ProjectDirectory::get(cx) else {
        return;
    };
    let Some(prompt) = self
        .prompts
        .iter_mut()
        .find(|prompt| prompt.prompt == which)
    else {
        return;
    };
    let text = prompt.editor.read(cx).value();
    prompt.error = system_prompts::save(which, &text, &project_dir)
        .err()
        .map(|err| format!("{err:#}").into());

